#!/bin/zsh
cd ~/dr-pfeiler-site; mkdir -p entwuerfe/szenen-v3
B=werkzeug/bild.py; S1=vorlagen/stil/ki-01-knie-reflexhammer.jpg
job(){ eval "$B edit --qualitaet high --format quer $@" & }
welle(){ wait; echo "--- Welle fertig $(date +%H:%M:%S)"; sleep 70; }
